// ═══════════════════════════════════════════════════════════
// VALIDATE INPUT — checks required fields + timestamp
// The webhook node wraps POST body inside $json.body
// ═══════════════════════════════════════════════════════════
const raw = $input.first().json;
const body = raw.body || raw; // unwrap webhook envelope
const errors = [];

// --- Determine source ---
const isWebsiteForm = body.source === 'website_form';
const isChatbot = body.event_type === 'new_enquiry';

if (!isWebsiteForm && !isChatbot) {
  errors.push('Unknown source: expected website_form or chatbot new_enquiry');
}

// --- Required fields ---
const email = isWebsiteForm ? body.form_data?.email : body.client?.email;
const name  = isWebsiteForm ? body.form_data?.name  : body.client?.name;

if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  errors.push('Invalid or missing email address');
}
if (!name || name.trim().length < 2) {
  errors.push('Invalid or missing name (min 2 chars)');
}

// --- Timestamp freshness (website form only, 5 min window) ---
if (isWebsiteForm && body.timestamp) {
  const ts = new Date(body.timestamp);
  const ageMs = Date.now() - ts.getTime();
  if (isNaN(ts.getTime()) || ageMs > 300000 || ageMs < -60000) {
    errors.push('Timestamp is missing, stale (>5 min), or in the future');
  }
}

if (errors.length > 0) {
  throw new Error('Validation failed: ' + errors.join('; '));
}

return [{ json: { ...body, _source: isWebsiteForm ? 'website' : 'chatbot' } }];

// ═══════════════════════════════════════════════════════════
// SPAM FILTER — honeypot, URL density, blocklist keywords
// ═══════════════════════════════════════════════════════════
const body = $input.first().json;
const formData = body.form_data || body.enquiry || {};
const message = formData.message || body.enquiry?.special_requests || body.conversation_summary || '';

// 1. Honeypot check (hidden field that bots fill in)
if (formData._hp_field) {
  throw new Error('SPAM_DETECTED: Honeypot field populated');
}

// 2. Link density (more than 3 URLs = suspicious)
const urlCount = (message.match(/https?:\/\//gi) || []).length;
if (urlCount > 3) {
  throw new Error('SPAM_DETECTED: Excessive URLs in message (' + urlCount + ')');
}

// 3. Blocklist keyword patterns
const spamPatterns = [
  /\bcrypto\b/i, /\bSEO\b/i, /\bbacklink/i,
  /\bcasino/i, /\bviagra/i, /click here.*free/i,
  /\bNFT\b/i, /\bweb3\b/i, /\bblockchain\b/i,
  /buy\s+followers/i, /\bpayday\s+loan/i
];
for (const pattern of spamPatterns) {
  if (pattern.test(message)) {
    throw new Error('SPAM_DETECTED: Blocked pattern match: ' + pattern.toString());
  }
}

// 4. Empty message from website form (not from chatbot which has conversation_summary)
if (body._source === 'website' && (!message || message.trim().length < 5)) {
  throw new Error('SPAM_DETECTED: Message too short or empty');
}

return [$input.first()];

// ═══════════════════════════════════════════════════════════
// MERGE — carry forward normalised data + Outlook message ID
// ═══════════════════════════════════════════════════════════
const outlookResponse = $input.first().json;
const prevData = $('Normalise Payload').first().json;

return [{
  json: {
    ...prevData,
    outlookMessageId: outlookResponse.id,
  }
}];

// ═══════════════════════════════════════════════════════════════
// PARSE CLAUDE RESPONSE — extract classification from JSON
// Claude Messages API: { content: [{ type: "text", text: "..." }] }
// ═══════════════════════════════════════════════════════════════
const prevData = $('Capture Message ID').first().json;
const claudeResponse = $input.first().json;

let classification;
try {
  const rawText = claudeResponse.content[0].text;
  // Strip markdown code fences if present
  const cleaned = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  classification = JSON.parse(cleaned);
} catch (e) {
  classification = {
    classification: 'IMPORTANT',
    reason: 'Claude response parse error — defaulting to IMPORTANT for safety',
    confidence: 0.0,
  };
}

// Validate classification value
const valid = ['IMMEDIATE', 'IMPORTANT', 'NOT_IMPORTANT'];
if (!valid.includes(classification.classification)) {
  classification.classification = 'IMPORTANT';
  classification.reason = 'Invalid classification value — defaulting to IMPORTANT';
}

return [{
  json: {
    ...prevData,
    classification: classification.classification,
    classificationReason: classification.reason,
    classificationConfidence: classification.confidence || 0,
  }
}];

// ═══════════════════════════════════════════════════════════════
// CLAUDE FALLBACK — API failed after retries, default safe
// ═══════════════════════════════════════════════════════════════
const prevData = $('Capture Message ID').first().json;

return [{
  json: {
    ...prevData,
    classification: 'IMPORTANT',
    classificationReason: 'Claude API unavailable — defaulting to IMPORTANT for human review',
    classificationConfidence: 0.0,
    classificationError: true,
  }
}];

// ═══════════════════════════════════════════════════════════════
// BUILD PATCH — construct the Outlook update body based on
// Claude classification
// ═══════════════════════════════════════════════════════════════
const data = $input.first().json;
const cls = data.classification;

const importanceMap = {
  'IMMEDIATE': 'high',
  'IMPORTANT': 'normal',
  'NOT_IMPORTANT': 'low',
};

const flagMap = {
  'IMMEDIATE': 'flagged',
  'IMPORTANT': 'notFlagged',
  'NOT_IMPORTANT': 'notFlagged',
};

return [{
  json: {
    ...data,
    outlookPatch: {
      categories: [cls],
      importance: importanceMap[cls] || 'normal',
      flag: {
        flagStatus: flagMap[cls] || 'notFlagged',
      },
    },
  }
}];

// ═══════════════════════════════════════════════════════════════
// CHATBOT LOG — for chatbot-sourced leads, just return OK
// (no webhook response needed — chatbot uses fire-and-forget)
// ═══════════════════════════════════════════════════════════════
return [{ json: { status: 'ok', source: 'chatbot', classification: $json.classification } }];

// ═══════════════════════════════════════════════════════════
// TO DO: BUILD TASK — map enquiry data → MS To Do API payload
// Runs in parallel with Route + Postgres after email is sent.
// Uses $('Build Outlook Patch').first().json for normalised data
// (HTTP Request nodes replace $json with API response).
//
// API: POST /me/todo/lists/{listId}/tasks
// Docs: https://learn.microsoft.com/en-us/graph/api/todotasklist-post-tasks
// ═══════════════════════════════════════════════════════════
const data = $('Build Outlook Patch').first().json;
const client = data.client || {};
const enquiry = data.enquiry || {};
const intelligence = data.intelligence || {};
const cls = data.classification || 'IMPORTANT';

// --- Importance mapping: Claude classification → To Do importance ---
// To Do supports: low, normal, high
const importanceMap = {
  'IMMEDIATE': 'high',
  'IMPORTANT': 'normal',
  'NOT_IMPORTANT': 'low',
};
const importance = importanceMap[cls] || 'normal';

// --- Task title ---
const destination = enquiry.destination || 'General';
const title = `[${cls}] ${client.name || 'Unknown'} — ${destination}`;

// --- Description (plain text) ---
const descParts = [
  `Name: ${client.name || 'N/A'}`,
  `Email: ${client.email || 'N/A'}`,
  `Phone: ${client.phone || 'Not provided'}`,
  `Destination: ${destination}`,
  `Travel Dates: ${enquiry.travel_dates || 'Flexible'}`,
  `Duration: ${enquiry.duration || 'TBD'}`,
  `Party: ${enquiry.adults || '?'} adults, ${enquiry.children || 0} children`,
  `Budget: ${enquiry.budget || 'Not specified'}`,
  `Experience: ${(enquiry.experience_type || []).join(', ') || 'Not specified'}`,
  `Lead Score: ${intelligence.lead_score || 'N/A'}`,
  `Booking Stage: ${intelligence.booking_stage || 'unknown'}`,
  `Urgency: ${intelligence.urgency || 'unknown'}`,
  `Classification: ${cls} (${data.classificationReason || 'N/A'})`,
  `Source: ${data._source || 'unknown'}`,
  '',
  'Message:',
  (enquiry.message || 'No message').substring(0, 1500),
];
const description = descParts.join('\n');

// --- Due date: 3 business days from now for follow-up ---
const now = new Date();
let dueDate = new Date(now);
let addedDays = 0;
while (addedDays < 3) {
  dueDate.setDate(dueDate.getDate() + 1);
  if (dueDate.getDay() !== 0 && dueDate.getDay() !== 6) addedDays++;
}

// --- Build the To Do task payload ---
const todoTask = {
  title: title.substring(0, 255),
  body: {
    content: description,
    contentType: 'text',
  },
  importance: importance,
  status: 'notStarted',
  dueDateTime: {
    dateTime: dueDate.toISOString().replace('Z', ''),
    timeZone: 'UTC',
  },
  categories: [cls],
};

// --- Build the API URL using the list ID from env ---
const listId = $env.TODO_LIST_ID;
const apiUrl = `https://graph.microsoft.com/v1.0/me/todo/lists/${listId}/tasks`;

return [{
  json: {
    todoTask,
    todoApiUrl: apiUrl,
    todoMeta: {
      clientEmail: client.email,
      clientName: client.name,
      classification: cls,
      source: data._source,
    },
  }
}];

// Power BI: Build Payload
// Transforms n8n payload to Power BI streaming dataset schema

const payload = $('Normalise Payload').first().json;
const classification = $('Parse Classification').first().json;

// Check if Power BI is configured
if (!$env.POWERBI_PUSH_URL || $env.POWERBI_PUSH_URL.includes('your-workspace')) {
  console.log('Power BI not configured - skipping push');
  return []; // Skip if not configured
}

// Build Power BI row (15 columns)
const powerbiRow = {
  enquiryId: $execution.id || `exec-${Date.now()}`,
  clientName: payload.clientName || 'Anonymous',
  clientEmail: payload.clientEmail || 'not-provided@example.com',
  destination: payload.destination || 'Not specified',
  classification: classification.classification || 'IMPORTANT',
  leadScore: parseInt(payload.lead_score || 50),
  budgetMax: parseFloat(payload.budget_max || 0),
  paxTotal: parseInt(payload.pax_adults || 0) + parseInt(payload.pax_children || 0),
  bookingStage: payload.booking_stage || 'considering',
  source: payload.source || 'website',
  assignedAgent: 'Unassigned', // Will be updated when To Do task is assigned
  createdDate: new Date().toISOString(),
  responseTimeSecs: Math.round((Date.now() - new Date(payload.submitted_at || Date.now()).getTime()) / 1000),
  classificationConfidence: parseFloat(classification.classificationConfidence || 0.8),
  urgency: classification.classification === 'IMMEDIATE' ? 'high' :
           classification.classification === 'IMPORTANT' ? 'medium' : 'low'
};

console.log('Power BI payload built:', JSON.stringify(powerbiRow, null, 2));
return [{ json: powerbiRow }];

